 Chapter Review.","independentNewReasoningClaimed":false,"semanticReviewer":"Codex automated author; independent human review pending"},"source":{"id":"ENG7-U01-MB-READ-A","kind":"reading","format":"passage","familyId":"4c308062-c912-5aca-8f99-1fcf33e96d75","title":"Reading source MB-A","locale":"en","text":"For a class project, Lilit photographed three people wearing the same borrowed coat. She expected their written descriptions of it to be alike. Instead, one person praised the deep pockets, another liked the bright lining, and the third said the coat was difficult to move in.\n\nLilit kept all three comments beside the photographs. The project was about people''s different experiences, so she did not replace the comments with one score for the coat. Readers could see what mattered to each person.","sourceReferences":[],"reviewStatus":"pending","registrationStatus":"unregistered","audioAvailable":false}}},{"itemId":"6e3f62bb-280d-5c17-aaf4-9fec555cdf87","itemCode":"ENG7-U01-MB-22","context":{"schemaVersion":"haiedu-authoring-review-v1","itemCode":"ENG7-U01-MB-22","version":1,"locale":"en","sourcePacket":"docs/content/english-7-unit-01-assessment-batch-bcd.json","sourceReference":"Grigoryan, English 7, Zangak 2023; pp. 17, 18; activities 19; programme T1.L2; docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-MB-22","hint":"Use the supplied information and preserve its meaning.","feedback":"The third person says the coat is difficult to move in.","optionFeedback":[{"key":"a","text":"Deep pockets are praised by the first person."},{"key":"b","text":"The bright lining is liked by the second person."},{"key":"c","text":"The third comment concerns movement."}],"fieldFeedback":[],"comparison":{"disposition":"protected_parallel_assessment_variant","protocol":"haiedu-protected-parallel-pilot-v1","authorization":"docs/evidence/english-7-unit-01-owner-acceptance-20261021.json","repeatedTaughtClaim":"Supported explicit detail from READ-A","nearestPractice":["E